 "content": "from collections import Counter

def transform(grid):
    """Replace 2-valued occlusion cells using the grid's dihedral symmetry."""
    g = [row[:] for row in grid]
    n, m = len(g), len(g[0])
    if n != m:
        raise ValueError("expected a square grid")
    def orbit(r, c):
        return {(r,c), (r,n-1-c), (n-1-r,c), (n-1-r,n-1-c),
                (c,r), (c,n-1-r), (n-1-c,r), (n-1-c,n-1-r)}
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 2:
                vals = [grid[rr][cc] for rr,cc in orbit(r,c) if grid[rr][cc] != 2]
                if not vals:
                    raise ValueError("no unoccluded symmetric cell")
                g[r][c] = Counter(vals).most_common(1)[0][0]
    return g

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
